from __future__ import annotations

import argparse
import csv
import io
import re
import sys
from datetime import date
from pathlib import Path

DATA = Path(__file__).resolve().parent.parent / "src" / "clinicalomx" / "vocab" / "data"

_CAT_RECORD = re.compile(r"cat\[Record\[([^\]]+)\]\]")

_TYPES_HEADER = """\
# GENERATED by scripts/dump_instance.py on {today} from live.
"""

_FEATURES_HEADER = """\
# GENERATED by scripts/dump_instance.py on {today} from live.
#
# Categorical dtypes are written as `type:<Name>`
#
# dtype: str | int | float | bool | datetime | num | Artifact | Record
#        type:<TypeName> | cat[ULabel] | cat[bionty.Protein]
# status: active | deprecated
"""


def collect_types(ln) -> list[dict]:
    out = []
    for t in ln.Record.filter(is_type=True).order_by("name"):
        entry = {"name": str(t.name), "uid": str(t.uid)}
        parent = getattr(t, "type", None)
        if parent is not None:
            entry["type"] = str(parent.name)
        if t.description:
            entry["description"] = str(t.description)
        out.append(entry)
    return out


def collect_features(ln, uid_to_type: dict[str, str]) -> tuple[list[dict], list[str]]:
    rows, unmapped = [], []
    for f in ln.Feature.filter().order_by("name"):
        raw = f._dtype_str or ""
        dtype, missing = _portable_dtype(raw, uid_to_type)
        if missing:
            unmapped.append(f"{f.name}: {raw}")
        rows.append({
            "name": str(f.name),
            "dtype": dtype,
            "description": str(f.description or ""),
            "coerce": "true" if getattr(f, "coerce_dtype", False) else "",
            "status": "active",
        })
    return rows, unmapped


def _portable_dtype(raw: str, uid_to_type: dict[str, str]) -> tuple[str, bool]:
    """``cat[Record[<uid>]]`` -> ``type:<Name>``; everything else passes through."""
    m = _CAT_RECORD.search(raw)
    if not m:
        return raw, False
    uid = m.group(1)
    name = uid_to_type.get(uid)
    if name is None:
        return raw, True  # dangling pin: kept verbatim
    return f"type:{name}", False


def write_types(types: list[dict]) -> None:
    import yaml

    body = yaml.safe_dump({"types": types}, sort_keys=False, allow_unicode=True)
    (DATA / "types.yaml").write_text(
        _TYPES_HEADER.format(today=date.today().isoformat()) + "\n" + body
    )


def write_features(rows: list[dict]) -> None:
    buf = io.StringIO()
    writer = csv.DictWriter(buf, fieldnames=["name", "dtype", "description", "coerce", "status"])
    writer.writeheader()
    writer.writerows(rows)
    (DATA / "features.csv").write_text(
        _FEATURES_HEADER.format(today=date.today().isoformat()) + buf.getvalue()
    )


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--write", action="store_true", help="overwrite data/types.yaml + features.csv")
    args = p.parse_args(argv)

    import lamindb as ln

    types = collect_types(ln)
    uid_to_type = {t["uid"]: t["name"] for t in types}
    features, unmapped = collect_features(ln, uid_to_type)
    schemas = list(ln.Schema.filter().order_by("name"))

    print(f"{len(types)} type record(s), {len(features)} feature(s), {len(schemas)} schema(s)")

    if unmapped:
        print("\nDANGLING categorical pins - dtype references a type UID that no "
              "longer exists (a delete-and-recreate happened at some point):")
        for line in unmapped:
            print(f"  {line}")

    if schemas:
        print("\nSchemas present in the instance.")
        for s in schemas:
            print(f"  {s.name}")

    if not args.write:
        print("\n(dry run - pass --write to update data/)")
        return 0

    write_types(types)
    write_features(features)
    print(f"\nwrote {DATA/'types.yaml'}\nwrote {DATA/'features.csv'}")
    print("\nNext: make steps/ declare exactly this, then `plan` until it is empty. "
          "Commit that as the baseline BEFORE fixing anything.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
